'use strict';

// MODULES //

var isNumberOrComplexLike = require( '@stdlib/assert-is-number-or-complex-like' ).isPrimitive;
var isNumber = require( '@stdlib/assert-is-number' ).isPrimitive;
var isFunction = require( '@stdlib/assert-is-function' );
var isDataType = require( '@stdlib/ndarray-base-assert-is-data-type' );
var constructorFactory = require( '@stdlib/ndarray-tensor0d-ctor-factory' );
var format = require( '@stdlib/string-format' );


// MAIN //

/**
* Returns a function for creating zero-dimensional ndarrays.
*
* @param {*} dtype - ndarray data type
* @param {(number|ComplexLike)} defaultValue - default value
* @param {Function} isValidScalar - function for checking whether a value is a valid scalar value
* @throws {TypeError} first argument must be a valid data type
* @throws {TypeError} second argument must be either a number or complex number-like object
* @throws {TypeError} third argument must be a function
* @returns {Function} function for creating zero-dimensional ndarrays
*
* @example
* var isNumberOrComplexLike = require( '@stdlib/assert-is-number-or-complex-like' ).isPrimitive;
* var ZERO = require( '@stdlib/constants-complex128-zero' );
*
* var Complex128Tensor0D = factory( 'complex128', ZERO, isNumberOrComplexLike );
*
* var arr = new Complex128Tensor0D();
* // returns <ndarray>[ <Complex128>[ 0.0, 0.0 ] ]
*
* @example
* var isNumberOrComplexLike = require( '@stdlib/assert-is-number-or-complex-like' ).isPrimitive;
* var ZERO = require( '@stdlib/constants-complex128-zero' );
*
* var Complex128Tensor0D = factory( 'complex128', ZERO, isNumberOrComplexLike );
*
* var arr = new Complex128Tensor0D( 1.0 );
* // returns <ndarray>[ <Complex128>[ 1.0, 0.0 ] ]
*
* @example
* var isNumberOrComplexLike = require( '@stdlib/assert-is-number-or-complex-like' ).isPrimitive;
* var ZERO = require( '@stdlib/constants-complex128-zero' );
* var ArrayBuffer = require( '@stdlib/array-buffer' );
*
* var Complex128Tensor0D = factory( 'complex128', ZERO, isNumberOrComplexLike );
*
* var buf = new ArrayBuffer( 16 );
* var arr = new Complex128Tensor0D( buf );
* // returns <ndarray>[ <Complex128>[ 0.0, 0.0 ] ]
*
* @example
* var isNumberOrComplexLike = require( '@stdlib/assert-is-number-or-complex-like' ).isPrimitive;
* var ZERO = require( '@stdlib/constants-complex128-zero' );
* var ArrayBuffer = require( '@stdlib/array-buffer' );
*
* var Complex128Tensor0D = factory( 'complex128', ZERO, isNumberOrComplexLike );
*
* var buf = new ArrayBuffer( 32 );
* var arr = new Complex128Tensor0D( buf, 16 );
* // returns <ndarray>[ <Complex128>[ 0.0, 0.0 ] ]
*/
function factory( dtype, defaultValue, isValidScalar ) {
	var ctor;
	if ( !isDataType( dtype ) ) {
		throw new TypeError( format( 'invalid argument. First argument must be a supported data type. Value: `%s`.', dtype ) );
	}
	if ( !isNumberOrComplexLike( defaultValue ) ) {
		throw new TypeError( format( 'invalid argument. Second argument must be either a number or complex number. Value: `%s`.', defaultValue ) );
	}
	if ( !isFunction( isValidScalar ) ) {
		throw new TypeError( format( 'invalid argument. Third argument must be a function. Value: `%s`.', isValidScalar ) );
	}
	ctor = constructorFactory( dtype, defaultValue, isValidScalar );
	return Tensor0D;

	/**
	* Returns a zero-dimensional ndarray.
	*
	* @private
	* @param {(ComplexLike|number|ArrayBuffer)} [value] - scalar, real component, or buffer
	* @param {(NonNegativeInteger|number)} [arg1] - byte offset or imaginary component
	* @param {Options} [options] - function options
	* @param {boolean} [options.readonly=false] - boolean indicating whether to return a read-only ndarray
	* @param {string} [options.order='row-major'] - memory layout (either row-major or column-major)
	* @throws {TypeError} first argument must be either a number, complex number, buffer, or options object
	* @throws {TypeError} must provide valid options
	* @returns {ndarray} zero-dimensional ndarray
	*/
	function Tensor0D( value ) {
		var nargs;
		var v;

		nargs = arguments.length;

		// Case: new Tensor0D()
		if ( nargs === 0 ) {
			return new ctor();
		}
		// Case: new Tensor0D( scalar|ArrayBuffer|options )
		if ( nargs === 1 ) {
			return new ctor( value );
		}
		// Case: new Tensor0D( arg0, arg1 )
		if ( nargs === 2 ) {
			// Case: new Tensor0D( re, im )
			if ( isNumber( value ) && isNumber( arguments[ 1 ] ) ) {
				v = {
					're': value,
					'im': arguments[ 1 ]
				};
				return new ctor( v );
			}
			// Case: new Tensor0D( scalar|ArrayBuffer, byteOffset|options )
			return new ctor( value, arguments[ 1 ] );
		}
		// Case: new Tensor0D( re, im, options )
		if ( isNumber( value ) && isNumber( arguments[ 1 ] ) ) {
			v = {
				're': value,
				'im': arguments[ 1 ]
			};
			return new ctor( v, arguments[ 2 ] );
		}
		// Case: new Tensor0D( ArrayBuffer, byteOffset, options )
		return new ctor( value, arguments[ 1 ], arguments[ 2 ] );
	}
}


// EXPORTS //

module.exports = factory;
